#!/usr/bin/env node
import { mkdir, cp } from "node:fs/promises"; import path from "node:path"; import { spawnSync } from "node:child_process"; import { compileWorkbook } from "../packages/compiler/compiler.js"; import { publishManifest, listVersions } from "../packages/compiler/publisher.js"; import { startServer } from "../server/api.js";
const root=process.cwd(), dataDir=path.join(root,"data"), workbook=path.join(dataDir,"workbooks","ad-runner.xlsx"), host=process.env.AD_RUNNER_HOST??"localhost", port=Number(process.env.AD_RUNNER_PORT??4178); const cmd=process.argv[2]??"serve", arg=process.argv[3]??workbook;
if(cmd==="import-simple-csv"){const csv=process.argv[3], target=process.argv[4]; if(!csv||!target){console.error("Usage: ad-runner import-simple-csv CSV WORKBOOK [--dry-run]");process.exit(2)} const result=spawnSync(process.env.PYTHON??"python3",[path.join(root,"simple_partner_csv.py"),csv,target,...process.argv.slice(5)],{stdio:"inherit"}); process.exit(result.status??1);} else if(cmd==="init"){await mkdir(path.join(dataDir,"workbooks"),{recursive:true}); await mkdir(path.join(dataDir,"sites"),{recursive:true}); await mkdir(path.join(dataDir,"events"),{recursive:true}); await cp(path.join(root,"examples/ad-runner-template.xlsx"),workbook,{force:true}); console.log(`Created ${workbook}\nControl panel: http://${host}:${port}/admin\nNext: npm run dev`);} else if(cmd==="serve"){await startServer({host,port,dataDir,rootDir:root,workbook});} else if(cmd==="validate"){const r=await compileWorkbook(arg); print(r); process.exit(r.valid?0:1);} else if(cmd==="compile"){const r=await compileWorkbook(arg); print(r); console.log(JSON.stringify(r.sites.map(s=>s.manifest).filter(Boolean),null,2)); process.exit(r.valid?0:1);} else if(cmd==="publish"){const r=await compileWorkbook(arg); print(r); if(!r.valid) process.exit(1); for(const s of r.sites) if(s.manifest) console.log(await publishManifest(dataDir,s.manifest));} else if(cmd==="status"){const r=await compileWorkbook(workbook).catch(e=>({sites:[],valid:false,error:String(e)} as any)); print(r); for(const s of r.sites??[]) if(s.site) console.log(s.site, await listVersions(dataDir,s.site));} else {console.error('Commands: init import-simple-csv serve validate compile publish status'); process.exit(2);} function print(r:any){for(const s of r.sites??[]){console.log(`\n[${s.sheetName}] ${s.site??''} ${s.errors?.length?'ERROR':'OK'}`); for(const w of s.warnings??[]) console.log('warning:',w); for(const e of s.errors??[]) console.log('error:',e);}}
